import{validate,createRun,complete,interpolate}from'./engine.js';
const root=document.querySelector('#root'),dialog=document.querySelector('#dialog'),key='document-flow-studio-v1';const blank=()=>({schema:1,workspace:'My workspace',workflows:[],runs:[],audit:[]});let db;try{db=JSON.parse(localStorage.getItem(key))||blank();}catch{db=blank();}let selected=null,tab='diagram',wireSource=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const uid=()=>crypto.randomUUID();
function persist(action,entity){if(action)db.audit.unshift({at:new Date().toISOString(),action,entity});try{localStorage.setItem(key,JSON.stringify(db));}catch{if(!persist.warned){persist.warned=true;toast('Browser storage is unavailable. This session still works; export a workspace backup before closing.');}}}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4200);}
function modal(title,body,handler){dialog.innerHTML=`<form id="modal-form"><h2>${esc(title)}</h2>${body}<div class="actions"><button type="button" data-close>Cancel</button>${handler?'<button class="primary" type="submit">Save</button>':''}</div></form>`;dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();try{handler?.(new FormData(e.currentTarget));dialog.close();render();}catch(err){toast(err.message)}};dialog.showModal();}
function download(name,value,type='application/json'){const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const btn=(label,action,cls='',id='')=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const empty=(title,desc,button='')=>`<div class="empty"><div class="symbol">▧</div><h2>${title}</h2><p>${desc}</p>${button}</div>`;
function layout(view,content){const nav=[['dashboard','◫','Dashboard'],['workflows','⌘','Workflows'],['templates','▤','Templates'],['documents','▧','Documents'],['inbox','▣','Inbox'],['bots','◇','Bots & integrations'],['audit','◷','Audit trail'],['settings','⚙','Workspace settings']];root.innerHTML=`<aside><div class="brand"><b>◈</b> Flow Studio</div><div class="workspace"><span class="avatar">${esc(db.workspace.slice(0,1))}</span><div>${esc(db.workspace)}<div class="muted">Browser workspace</div></div></div>${btn('+ Create','create','primary')}<nav style="margin-top:17px">${nav.map(([id,icon,label])=>`<a href="#/${id}" class="${view===id?'active':''}">${icon}&nbsp; ${label}${id==='inbox'?` <span class="badge">${pendingCount()}</span>`:''}</a>`).join('')}</nav><div class="foot">Independent Altaflow research recreation.<br>Local data · no external sends.<a href="TECHNICAL_SPEC.md" target="_blank">Technical design ↗</a><a href="SOURCES.md" target="_blank">Research & scope ↗</a></div></aside><main><header><div class="row"><button class="menu-toggle" data-action="menu" aria-label="Toggle navigation">☰</button><span>${esc(view==='editor'?'Workflow designer':nav.find(n=>n[0]===view)?.[2]||'Workspace')}</span></div><div class="actions"><span class="badge">Independent implementation</span><span class="avatar">You</span></div></header><div class="content">${content}</div></main>`;root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id));root.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{selected=b.dataset.step;render()});root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});bindGraph();root.querySelectorAll('[draggable]').forEach(n=>{n.ondragstart=e=>e.dataTransfer.setData('text/plain',n.dataset.node);n.ondragover=e=>e.preventDefault();n.ondrop=e=>{e.preventDefault();reorder(e.dataTransfer.getData('text/plain'),n.dataset.node)}});}
function pendingCount(){return db.runs.reduce((n,r)=>n+Object.values(r.states).filter(s=>s==='ready').length,0)}
function cards(items){return `<div class="grid">${items.map(w=>`<div class="card"><div class="row"><span class="pill">${esc(w.kind)}</span><span class="muted">v${w.version} · ${esc(w.status)}</span></div><h2 style="margin-top:18px">${esc(w.name)}</h2><p>${w.documents.length} documents · ${w.fields.length} fields · ${w.steps.length} steps</p><div class="actions"><a href="#/editor/${w.id}">${btn('Configure','noop')}</a>${btn('Start local run','run','',w.id)}${btn('Duplicate','duplicate','',w.id)}${btn('Archive','archive','danger',w.id)}</div></div>`).join('')}</div>`;}
function dashboard(){const active=db.workflows.filter(w=>!w.archived);return `<div class="row"><div><h1>Your document workspace</h1><p>Create a process, collect information, and route documents through your team.</p></div><div class="actions">${btn('Load sample workflow','load-sample')}${btn('+ Create','create','primary')}</div></div><div class="stats">${[['Workflows',active.filter(w=>w.kind==='workflow').length],['Local documents',db.runs.length],['Awaiting action',pendingCount()],['Completed',db.runs.filter(r=>r.status==='completed').length]].map(([t,n])=>`<div class="stat">${t}<strong>${n}</strong></div>`).join('')}</div><h2>Recent workflows</h2>${active.length?cards(active.slice(-6)):empty('Build your first document process','Start with a reusable workflow, a document template, or a one-time document package.',btn('Create your first workflow','create','primary'))}<details><summary>What runs here?</summary><p>This independent implementation runs form capture, conditions, local approvals, value/tag bots and document exports inside your browser. Identity-verified signatures, CRM, email, AI and server scheduling are not connected.</p></details>`;}
function creation(){modal('Create a document process',`<div class="modal-grid">${[['workflow','Design workflow','Documents, recipient steps, branches and local bots'],['template','Create template','Reusable documents with fields and recipient roles'],['one-time','Send documents','A one-time package without automation']].map(([k,t,s])=>`<button type="button" data-kind="${k}">${t}<small>${s}</small></button>`).join('')}</div>`);dialog.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{dialog.close();newWorkflow(b.dataset.kind)})}
function newWorkflow(kind){modal(kind==='workflow'?'Design workflow':kind==='template'?'Create template':'One-time document package','<label>Name</label><input name="name" required placeholder="Name your process" maxlength="100">',f=>{const w={id:uid(),name:f.get('name').trim(),kind,status:'draft',version:1,documents:[],fields:[],steps:[],versions:[],archived:false};if(!w.name)throw Error('Enter a name');db.workflows.push(w);persist('workflow.created',w.name);selected=null;tab='documents';location.hash='/editor/'+w.id;})}
function workflow(){const id=location.hash.split('/')[2];return db.workflows.find(w=>w.id===id)}
function editor(w){if(!w)return empty('Workflow not found','Choose a workflow from your workspace.');const step=w.steps.find(s=>s.id===selected);return `<div class="row"><div><a href="#/workflows">← Workflows</a><h1 style="margin-top:10px">${esc(w.name)}</h1><span class="pill">${esc(w.kind)}</span> <span class="muted">Version ${w.version} · ${esc(w.status)}</span></div><div class="actions">${btn('Rename','rename','',w.id)}${btn('Versions','versions','',w.id)}${btn('Save version','save-version','',w.id)}${btn('Publish locally','publish','',w.id)}${btn('Start local run','run','primary',w.id)}</div></div><div class="tabs">${[['documents','Documents and forms'],['diagram','Workflow diagram'],['preview','Document preview']].map(([id,t])=>`<button data-tab="${id}" class="${tab===id?'selected':''}">${t}</button>`).join('')}</div>${tab==='documents'?documentsEditor(w):tab==='preview'?preview(w):`<div class="row" style="margin-bottom:16px"><div class="actions">${btn('+ Add a step','add-step','',w.id)}${btn('+ Add parallel branch','branch','',w.id)}${btn('+ Add local bot','add-bot','',w.id)}</div><span class="muted">Move nodes · connect Output → Input · select a wire to remove it</span></div><div class="editor">${graph(w)}<div class="inspector"><h2>${step?'Step settings':'Design your flow'}</h2><p>${step?esc(step.name):'Each step represents a recipient role or a local automation. Select a step to configure it.'}</p>${step?`${btn('Configure step','configure','primary',step.id)}<label>Predecessors</label><p>${step.after.map(id=>esc(w.steps.find(s=>s.id===id)?.name||'Missing')).join(', ')||'None'}</p><label>Execution condition</label><p>${step.condition?.field?esc(step.condition.field+' '+step.condition.op+' '+step.condition.value):'Always'}</p>`:''}<div class="banner">Steps are local workspace actions. No email is sent and no external identity is verified.</div></div></div>`}`;}
function documentsEditor(w){return `<div class="split"><div><div class="row"><h2>Documents</h2><div class="actions">${btn('+ Add document','add-document','',w.id)}${btn('Import text file','import-text','',w.id)}</div></div>${w.documents.map(d=>`<div class="field-card"><div class="row"><div><strong>${esc(d.title)}</strong><div class="muted">Plain-text generation template</div></div>${btn('Edit','edit-document','',d.id)}</div><p style="white-space:pre-wrap">${esc(d.body.slice(0,180))}</p></div>`).join('')||'<p>Add a document and use {{field_key}} to insert collected values.</p>'}</div><div><div class="row"><h2>Fillable fields</h2>${btn('+ Add field','add-field','',w.id)}</div>${w.fields.map(f=>`<div class="field-card"><div class="row"><strong>${esc(f.label)}</strong>${btn('Edit','edit-field','',f.id)}</div><span class="muted">${esc(f.key)} · ${esc(f.type)}${f.required?' · Required':''}</span></div>`).join('')||'<p>Create fields for the data your documents need.</p>'}</div></div>`;}
function preview(w){return `<h2>Generated document preview</h2><p>Placeholders are filled with the last local run’s values when available.</p>${w.documents.map(d=>`<div class="card" style="margin-bottom:20px"><h2>${esc(d.title)}</h2><div class="document">${esc(interpolate(d.body,db.runs.filter(r=>r.definition.id===w.id).at(-1)?.data||{}))}</div></div>`).join('')||empty('No documents yet','Add a document in the Documents and forms tab.')}`;}
function addStep(w,type='form',branch=false){if(w.kind!=='workflow'&&(type==='bot'||branch))throw Error('Bots and branches belong to workflow mode');const after=branch?(w.steps.find(s=>s.id===selected)?.after||[]):w.steps.length?[w.steps.at(-1).id]:[];modal(type==='bot'?'Add local bot':branch?'Add parallel recipient':'Add recipient step',`<label>Step name</label><input name="name" required placeholder="e.g. Manager review"><label>Step type</label><select name="type">${(type==='bot'?['bot']:['form','approval','acknowledgement']).map(x=>`<option value="${x}">${x}</option>`).join('')}</select>`,f=>{const s={id:uid(),name:f.get('name').trim(),type:f.get('type'),after,recipient:'',condition:null,bot:'tag',field:'',value:''};w.steps.push(s);selected=s.id;w.status='draft';persist('step.created',s.name)})}
function configure(w,s){modal('Configure '+s.name,`<label>Name</label><input name="name" value="${esc(s.name)}" required><label>Recipient label / email (stored locally only)</label><input name="recipient" value="${esc(s.recipient)}"><label>Execution condition</label><select name="field"><option value="">Always execute</option>${w.fields.map(f=>`<option ${s.condition?.field===f.key?'selected':''} value="${esc(f.key)}">${esc(f.label)}</option>`).join('')}</select><div class="form-row" style="margin-top:8px"><select name="op">${[['eq','Equals'],['neq','Does not equal'],['gt','Greater than'],['lt','Less than'],['contains','Contains'],['filled','Is not empty']].map(([v,t])=>`<option value="${v}" ${s.condition?.op===v?'selected':''}>${t}</option>`).join('')}</select><input name="value" placeholder="Condition value" value="${esc(s.condition?.value||'')}"></div>${s.type==='bot'?`<label>Local bot action</label><select name="bot"><option value="tag" ${s.bot==='tag'?'selected':''}>Add a tag to this run</option><option value="prefill" ${s.bot==='prefill'?'selected':''}>Fill a field with a fixed value</option></select><label>Target field</label><select name="target"><option value="">Select field</option>${w.fields.map(f=>`<option value="${esc(f.key)}" ${s.field===f.key?'selected':''}>${esc(f.label)}</option>`).join('')}</select><label>Tag or fixed value</label><input name="fixed" value="${esc(s.value)}">`:''}`,f=>{s.name=f.get('name').trim();s.recipient=f.get('recipient');s.condition=f.get('field')?{field:f.get('field'),op:f.get('op'),value:f.get('value')}:null;if(s.type==='bot'){s.bot=f.get('bot');s.field=f.get('target');s.value=f.get('fixed');if(s.bot==='prefill'&&!s.field)throw Error('Select a target field');}w.status='draft';persist('step.configured',s.name)})}
function reorder(a,b){let w=workflow();if(!w||a===b)return;let i=w.steps.findIndex(s=>s.id===a),j=w.steps.findIndex(s=>s.id===b);if(i<0||j<0)return;let s=w.steps.splice(i,1)[0];w.steps.splice(j,0,s);w.steps.forEach((s,i)=>s.after=i?[w.steps[i-1].id]:[]);w.status='draft';persist('steps.reordered',w.name);render();toast('Order saved; routing is now sequential')}
function runDialog(w){validate(w);modal('Start local run',`<p>Enter data for a browser-only document package. No invitations or external sends occur.</p>${w.fields.map(f=>`<label>${esc(f.label)}${f.required?' *':''}</label><input name="${esc(f.key)}" type="${f.type==='number'?'number':f.type==='email'?'email':f.type==='date'?'date':'text'}" value="${esc(w.sampleData?.[f.key]||'')}" ${f.required?'required':''}>`).join('')}`,f=>{let r=createRun(w,Object.fromEntries(f.entries()));db.runs.push(r);persist('run.started',r.name);location.hash='/run/'+r.id})}
function runPage(r){if(!r)return empty('Run not found','Open a document from your workspace.');return `<div class="row"><div><a href="#/documents">← Documents</a><h1 style="margin-top:10px">${esc(r.name)}</h1><span class="pill ${r.status==='completed'?'ok':''}">${esc(r.status)}</span> <span class="muted">Pinned version ${r.version} · Local run</span></div>${btn('Download document package','download-run','',r.id)}</div><div class="banner">Actions below are recorded as local browser actions. They are not identity-verified signatures or invitations sent to external recipients.</div>${graph(r.definition,r)}<div class="split"><div><h2>Document status</h2>${r.definition.steps.map(s=>`<div class="field-card"><div class="row"><strong>${esc(s.name)}</strong><span class="pill ${r.states[s.id]==='completed'?'ok':''}">${esc(r.states[s.id])}</span></div><div class="muted">${esc(s.type)} · ${esc(s.recipient||'Current browser user')}</div>${r.status==='in_progress'&&r.states[s.id]==='ready'?`<div class="actions" style="margin-top:16px">${btn(s.type==='approval'?'Approve locally':s.type==='acknowledgement'?'Record local acknowledgement':'Complete local form','complete-step','primary',r.id+':'+s.id)}${btn('Decline','decline-step','danger',r.id+':'+s.id)}</div>`:''}</div>`).join('')}<h2 style="margin-top:28px">Event history</h2>${r.events.map(e=>`<p class="muted">${esc(new Date(e.at).toLocaleString())} · ${esc(e.action)} · ${esc(e.step)}</p>`).join('')}</div><div><h2>Generated documents</h2>${r.definition.documents.map(d=>`<div class="card" style="margin-bottom:18px"><h2>${esc(d.title)}</h2><div class="document">${esc(interpolate(d.body,r.data))}</div></div>`).join('')}<h3>Collected data</h3><pre>${esc(JSON.stringify(r.data,null,2))}</pre>${r.tags.length?`<p>Tags: ${r.tags.map(esc).join(', ')}</p>`:''}</div></div>`;}
function action(name,id){try{let w=workflow();switch(name){case'noop':return;case'load-sample':loadSample();return;case'menu':root.querySelector('aside').classList.toggle('open');return;case'create':creation();return;case'rename':modal('Rename process',`<label>Name</label><input name="name" value="${esc(w.name)}" required>`,f=>{w.name=f.get('name').trim();persist('workflow.renamed',w.name)});return;case'add-step':addStep(w);return;case'branch':addStep(w,'form',true);return;case'add-bot':addStep(w,'bot');return;case'configure':configure(w,w.steps.find(s=>s.id===id));return;case'remove-step':{const s=w.steps.find(s=>s.id===id);if(!confirm('Remove '+s.name+'? Dependent steps will inherit its predecessors.'))return;w.steps=w.steps.filter(s=>s.id!==id);w.steps.forEach(t=>{if(t.after.includes(id))t.after=[...new Set([...t.after.filter(x=>x!==id),...s.after])]});selected=null;w.status='draft';persist('step.removed',s.name);break;}case'up':case'down':{let i=w.steps.findIndex(s=>s.id===id),j=i+(name==='up'?-1:1);if(j>=0&&j<w.steps.length)reorder(id,w.steps[j].id);return;}case'add-document':case'edit-document':{let d=w.documents.find(d=>d.id===id);modal(d?'Edit document':'Add document',`<label>Document title</label><input name="title" required value="${esc(d?.title||'')}" placeholder="Name this document"><label>Document content</label><textarea name="body" placeholder="Write content and insert {{field_key}} placeholders">${esc(d?.body||'')}</textarea>`,f=>{let entry={id:d?.id||uid(),title:f.get('title').trim(),body:f.get('body')};if(d)Object.assign(d,entry);else w.documents.push(entry);w.status='draft';persist('document.saved',entry.title)});return;}case'import-text':{const input=document.createElement('input');input.type='file';input.accept='.txt,text/plain';input.onchange=async()=>{try{let f=input.files[0];if(!f)return;if(f.size>500000)throw Error('Choose a text file under 500KB');w.documents.push({id:uid(),title:f.name,body:await f.text()});w.status='draft';persist('document.imported',f.name);render();}catch(e){toast(e.message)}};input.click();return;}case'add-field':case'edit-field':{let field=w.fields.find(f=>f.id===id);modal(field?'Edit field':'Add fillable field',`<label>Label</label><input name="label" required value="${esc(field?.label||'')}" placeholder="e.g. Full name"><label>Field key</label><input name="key" pattern="[A-Za-z][A-Za-z0-9_]*" required value="${esc(field?.key||'')}" placeholder="e.g. full_name"><label>Type</label><select name="type">${['text','email','number','date'].map(t=>`<option ${field?.type===t?'selected':''}>${t}</option>`).join('')}</select><label><input name="required" type="checkbox" ${field?.required?'checked':''}> Required field</label>`,f=>{const k=f.get('key');if(w.fields.some(x=>x.key===k&&x.id!==field?.id))throw Error('Choose a unique field key');let entry={id:field?.id||uid(),label:f.get('label').trim(),key:k,type:f.get('type'),required:f.has('required')};if(field)Object.assign(field,entry);else w.fields.push(entry);w.status='draft';persist('field.saved',entry.key)});return;}case'publish':validate(w);w.status='published';persist('workflow.published_locally',w.name);toast('Published in this browser workspace');break;case'save-version':{validate(w);const snap=structuredClone(w);delete snap.versions;w.versions.push({number:w.version,snapshot:snap,at:new Date().toISOString()});w.version++;w.status='draft';persist('version.saved',w.name);toast('Version snapshot saved');break;}case'versions':modal('Version history',`<p>Current: v${w.version} · ${esc(w.status)}</p>${w.versions.map(v=>`<div class="field-card">v${v.number} · ${esc(new Date(v.at).toLocaleString())} ${btn('Restore as new version','restore','',v.number)}</div>`).join('')||'<p>No saved snapshots yet.</p>'}`);dialog.querySelectorAll('[data-action=restore]').forEach(b=>b.onclick=()=>{let v=w.versions.find(v=>v.number===Number(b.dataset.id));let history=w.versions;let next=w.version+1;Object.assign(w,structuredClone(v.snapshot),{version:next,versions:history,status:'draft'});persist('version.restored',w.name);dialog.close();render()});return;case'run':runDialog(db.workflows.find(w=>w.id===id));return;case'duplicate':{const from=db.workflows.find(w=>w.id===id);const copy=structuredClone(from);copy.id=uid();copy.name+=' — Copy';copy.version=1;copy.versions=[];copy.status='draft';db.workflows.push(copy);persist('workflow.duplicated',copy.name);break;}case'archive':{const t=db.workflows.find(w=>w.id===id);if(!confirm('Archive '+t.name+'?'))return;t.archived=true;persist('workflow.archived',t.name);break;}case'complete-step':case'decline-step':{const[rid,sid]=id.split(':');const r=db.runs.find(r=>r.id===rid),s=r.definition.steps.find(s=>s.id===sid);if(name==='decline-step'){if(!confirm('Decline this local package?'))return;complete(r,sid,'decline');}else if(s.type==='acknowledgement'){modal('Local acknowledgement','<p>This records a browser action only. Identity verification and legally enforceable eSignature require a production signing service.</p><label>Typed name</label><input name="name" required><label><input type="checkbox" name="consent" required> I acknowledge this local test document.</label>',f=>{r.data['_acknowledgement_'+sid]=f.get('name');complete(r,sid);persist('local_acknowledgement.recorded',r.name)});return;}else complete(r,sid);persist('local_step.action',s.name);break;}case'download-run':{const r=db.runs.find(r=>r.id===id);download('document-package.json',r);return;}case'backup':download('flow-studio-backup.json',db);return;case'import-backup':{const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{let file=input.files[0];if(!file)return;if(file.size>5000000)throw Error('Backup exceeds 5MB');let data=JSON.parse(await file.text());if(data.schema!==1||!Array.isArray(data.workflows)||!Array.isArray(data.runs)||!Array.isArray(data.audit))throw Error('Invalid workspace backup');data.workflows.forEach(w=>{if(typeof w.id!=='string'||typeof w.name!=='string'||!Array.isArray(w.documents)||!Array.isArray(w.fields)||!Array.isArray(w.steps)||!Array.isArray(w.versions))throw Error('Invalid workflow record');w.documents.forEach(d=>{if(typeof d.title!=='string'||typeof d.body!=='string')throw Error('Invalid document record')});w.steps.forEach(s=>{if(typeof s.id!=='string'||typeof s.name!=='string'||!Array.isArray(s.after))throw Error('Invalid step record')});if(w.status==='published')validate(w)});data.runs.forEach(r=>{if(!r.definition||!r.states||!r.data||!Array.isArray(r.events)||!Array.isArray(r.tags))throw Error('Invalid run record');validate(r.definition)});if(!confirm('Replace this browser workspace? Export your existing data first.'))return;db=data;persist('backup.restored','workspace');render();}catch(e){toast(e.message)}};input.click();return;}case'workspace':modal('Workspace settings',`<label>Workspace name</label><input name="name" required value="${esc(db.workspace)}">`,f=>{db.workspace=f.get('name').trim();persist('workspace.renamed',db.workspace)});return;case'blocked':toast('External services are not connected. This build does not send messages, access CRM accounts or call AI models.');return;}}catch(e){toast(e.message)}render();}
function render(){const sampleEntry=location.pathname.endsWith('/sample.html')||new URLSearchParams(location.search).get('sample')==='supplier-review';const missingEditor=location.hash.startsWith('#/editor/')&&!workflow();if(location.hash==='#/sample'||(sampleEntry&&(!location.hash||missingEditor))){loadSample();return;}const path=location.hash.slice(2).split('/'),view=path[0]||'dashboard';let content='';if(view==='dashboard')content=dashboard();else if(view==='workflows'||view==='templates'){const list=db.workflows.filter(w=>!w.archived&&(view!=='templates'||w.kind==='template'));content=`<div class="row"><div><h1>${view==='templates'?'Templates':'Workflows'}</h1><p>${view==='templates'?'Reusable document packages and field definitions.':'Design and configure your document processes.'}</p></div>${btn('+ Create','create','primary')}</div>${list.length?cards(list):empty('Nothing here yet','Create your own process. There are no preloaded example cases.',btn('+ Create','create','primary'))}`;}else if(view==='editor')content=editor(workflow());else if(view==='run')content=runPage(db.runs.find(r=>r.id===path[1]));else if(view==='documents'||view==='inbox'){content=`<h1>${view==='inbox'?'Inbox':'Documents'}</h1><p>${view==='inbox'?'Local tasks ready for your action.':'Document packages created by your local workflow runs.'}</p>${db.runs.length?`<div class="card">${db.runs.filter(r=>view!=='inbox'||Object.values(r.states).includes('ready')).map(r=>`<a class="listlink" href="#/run/${r.id}"><div class="row"><strong>${esc(r.name)}</strong><span class="pill">${esc(r.status)}</span></div><span class="muted">v${r.version} · ${esc(new Date(r.createdAt).toLocaleString())}</span></a>`).join('')||'<p>No pending local tasks.</p>'}</div>`:empty('No document packages','Start a local run from a workflow to collect data and generate your first document.')}`;}else if(view==='bots')content=`<h1>Bots & integrations</h1><p>Local value and tag actions can be added in the workflow diagram. External connections are intentionally disconnected.</p><div class="grid">${['Pre-fill a fixed value','Add a run tag','Salesforce','Microsoft Dynamics','NetSuite','Google Drive','SharePoint','Email & SMS','AI extraction / Assistant'].map((n,i)=>`<div class="card"><span class="pill">${i<2?'Local bot available':'Requires external service'}</span><h2 style="margin-top:18px">${n}</h2><p>${i<2?'Configure within a workflow and inspect the actual local event history.':'A production backend, credentials and explicit authorization are required.'}</p>${i>=2?btn('View requirements','blocked'):''}</div>`).join('')}</div>`;else if(view==='audit')content=`<h1>Audit trail</h1><p>Actual local workspace actions. Browser storage is editable and is not a compliance-grade audit system.</p>${db.audit.length?`<div class="scroll"><table><thead><tr><th>Time</th><th>Event</th><th>Entity</th></tr></thead><tbody>${db.audit.map(a=>`<tr><td>${esc(new Date(a.at).toLocaleString())}</td><td>${esc(a.action)}</td><td>${esc(a.entity)}</td></tr>`).join('')}</tbody></table></div>`:empty('No activity recorded','Your actions will appear here as you build and use this workspace.')}`;else if(view==='settings')content=`<h1>Workspace settings</h1><p>Your data is kept on this browser and origin only.</p><div class="card"><h2>${esc(db.workspace)}</h2>${btn('Rename workspace','workspace')}<hr style="border:0;border-top:1px solid #eee;margin:24px 0"><h2>Backup & recovery</h2><p>Download a JSON backup before clearing browser data. Importing a backup replaces the current workspace after confirmation.</p><div class="actions">${btn('Export workspace','backup','primary')}${btn('Restore backup','import-backup')}</div><h2 style="margin-top:28px">Production features</h2><p>SSO, real team roles, tenant isolation, encrypted credential vaults, tamper-evident audit storage and retention are specified in the technical design. They are not enforced by this browser-only build.</p><a href="TECHNICAL_SPEC.md" target="_blank">Read system design ↗</a></div>`;else content=empty('Page not found','Return to your dashboard.','<a href="#/dashboard">Open dashboard</a>');layout(view,content);}
window.addEventListener('hashchange',()=>{selected=null;wireSource=null;render()});render();


function graph(w,run=null){
 const positions=w.steps.map((s,i)=>({s,x:Number.isFinite(s.x)?s.x:80+(i%3)*300,y:Number.isFinite(s.y)?s.y:80+Math.floor(i/3)*200}));
 const width=Math.max(1000,...positions.map(p=>p.x+320)),height=Math.max(600,...positions.map(p=>p.y+230));
 const edges=positions.flatMap(p=>p.s.after.map(id=>{const q=positions.find(n=>n.s.id===id);if(!q)return '';const x=q.x+240,y=q.y+65,tx=p.x,ty=p.y+65;return `<g class="graph-edge" data-from="${esc(id)}" data-to="${esc(p.s.id)}"><path d="M${x} ${y} C${x+90} ${y} ${tx-90} ${ty} ${tx} ${ty}"/><title>${esc(q.s.name)} → ${esc(p.s.name)}${run?'':' · Click to disconnect'}</title></g>`})).join('');
 return `<section class="graph-section" data-workflow="${esc(w.id)}" data-readonly="${!!run}"><div class="graph-tools"><strong>${run?'Execution graph':'Workflow canvas'}</strong><button data-zoom="-">−</button><span class="zoom-label">100%</span><button data-zoom="+">+</button><button data-zoom="reset">Reset view</button><span class="graph-hint">${run?'Select a node to inspect its state below':'Output → Input connects nodes; click a wire to disconnect'}</span></div><div class="graph-scroll"><div class="graph-stage" style="width:${width}px;height:${height}px"><svg class="graph-wires" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 L10 5 L0 10Z" fill="#7863cf"/></marker></defs>${edges}</svg>${positions.map(p=>`<article class="graph-node ${selected===p.s.id?'selected':''} state-${run?.states[p.s.id]||'draft'}" data-graph-node="${esc(p.s.id)}" style="left:${p.x}px;top:${p.y}px"><div class="graph-grip" tabindex="0">⠿ ${esc(p.s.type)} <span>${esc(run?.states[p.s.id]||'draft')}</span></div><strong>${esc(p.s.name)}</strong><small>${esc(p.s.condition?`${p.s.condition.field} ${p.s.condition.op} ${p.s.condition.value}`:p.s.type==='bot'?`${p.s.bot}: ${p.s.value}`:p.s.recipient||'Current browser user')}</small>${run?'':`<div class="graph-ports"><button data-input="${esc(p.s.id)}" title="Connect selected output here">● Input</button><button data-output="${esc(p.s.id)}" title="Start a connection">Output ●</button></div><button data-config-node="${esc(p.s.id)}">Configure</button><button data-delete-node="${esc(p.s.id)}" aria-label="Remove ${esc(p.s.name)}">×</button>`}</article>`).join('')}${!w.steps.length?'<p class="graph-empty">Add a step or bot above, then connect nodes to build your workflow.</p>':''}</div></div></section>`;
}
function bindGraph(){document.querySelectorAll('.graph-section').forEach(section=>{
 const w=db.workflows.find(w=>w.id===section.dataset.workflow),readonly=section.dataset.readonly==='true',stage=section.querySelector('.graph-stage');let zoom=1;
 section.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{zoom=b.dataset.zoom==='reset'?1:Math.max(.4,Math.min(1.8,zoom+(b.dataset.zoom==='+'?.1:-.1)));stage.style.transform=`scale(${zoom})`;stage.style.transformOrigin='0 0';section.querySelector('.zoom-label').textContent=Math.round(zoom*100)+'%'});
 if(readonly)return;
 section.querySelectorAll('[data-output]').forEach(b=>b.onclick=()=>{wireSource=b.dataset.output;section.querySelectorAll('[data-output]').forEach(n=>n.classList.toggle('primary',n===b));section.querySelector('.graph-hint').textContent='Choose the destination Input port';});
 section.querySelectorAll('[data-input]').forEach(b=>b.onclick=()=>{if(!wireSource)return toast('Select an Output port first');const target=w.steps.find(s=>s.id===b.dataset.input);if(wireSource===target.id)return toast('A node cannot connect to itself');if(target.after.includes(wireSource))return toast('These nodes are already connected');target.after.push(wireSource);try{const marks=new Set();function cycle(id){if(id===target.id)return true;if(marks.has(id))return false;marks.add(id);return w.steps.find(s=>s.id===id).after.some(cycle)}if(w.steps.find(s=>s.id===wireSource).after.some(cycle))throw Error('Connection would create a cycle');w.status='draft';persist('connection.created',w.name);wireSource=null;render()}catch(e){target.after.pop();toast(e.message)}});
 section.querySelectorAll('.graph-edge').forEach(edge=>edge.onclick=()=>{w.steps.find(s=>s.id===edge.dataset.to).after=w.steps.find(s=>s.id===edge.dataset.to).after.filter(id=>id!==edge.dataset.from);w.status='draft';persist('connection.removed',w.name);render()});
 section.querySelectorAll('[data-config-node]').forEach(b=>b.onclick=()=>configure(w,w.steps.find(s=>s.id===b.dataset.configNode)));
 section.querySelectorAll('[data-delete-node]').forEach(b=>b.onclick=()=>action('remove-step',b.dataset.deleteNode));
 section.querySelectorAll('.graph-node').forEach(node=>{const step=w.steps.find(s=>s.id===node.dataset.graphNode),grip=node.querySelector('.graph-grip');node.onclick=e=>{if(e.target.closest('button')||e.target===grip)return;selected=step.id;render()};grip.onpointerdown=e=>{e.preventDefault();grip.setPointerCapture(e.pointerId);const startX=e.clientX,startY=e.clientY,x=parseFloat(node.style.left),y=parseFloat(node.style.top);grip.onpointermove=e=>{step.x=Math.max(0,Math.round(x+(e.clientX-startX)/zoom));step.y=Math.max(0,Math.round(y+(e.clientY-startY)/zoom));node.style.left=step.x+'px';node.style.top=step.y+'px';section.querySelectorAll('.graph-edge').forEach(edge=>{const a=w.steps.find(s=>s.id===edge.dataset.from),b=w.steps.find(s=>s.id===edge.dataset.to),an=section.querySelector(`[data-graph-node="${a.id}"]`),bn=section.querySelector(`[data-graph-node="${b.id}"]`);const ax=parseFloat(an.style.left)+240,ay=parseFloat(an.style.top)+65,bx=parseFloat(bn.style.left),by=parseFloat(bn.style.top)+65;edge.querySelector('path').setAttribute('d',`M${ax} ${ay} C${ax+90} ${ay} ${bx-90} ${by} ${bx} ${by}`)});};grip.onpointerup=()=>{grip.onpointermove=null;persist('node.moved',step.name);render()};grip.onpointercancel=grip.onpointerup};
 grip.onkeydown=e=>{const move={ArrowLeft:[-20,0],ArrowRight:[20,0],ArrowUp:[0,-20],ArrowDown:[0,20]}[e.key];if(move){e.preventDefault();step.x=Math.max(0,parseFloat(node.style.left)+move[0]);step.y=Math.max(0,parseFloat(node.style.top)+move[1]);persist('node.moved',step.name);render()}};
 });
 });}

function loadSample(){
 let w=db.workflows.find(w=>w.sampleKey==='supplier-review-v1'&&!w.archived);
 if(!w){const ids=Array.from({length:6},uid),step=(i,name,type,after,x,y,extra={})=>({id:ids[i],name,type,after:after.map(n=>ids[n]),x,y,recipient:'',condition:null,bot:'tag',field:'',value:'',...extra});
 w={id:'sample-supplier-review-v1'+(db.workflows.some(w=>w.id==='sample-supplier-review-v1')?'-'+uid():''),sampleKey:'supplier-review-v1',name:'Sample · Supplier agreement review',kind:'workflow',status:'draft',version:1,archived:false,versions:[],sampleData:{supplier:'Example Studio',amount:'15000',contact:'reviewer@example.com',status:'Under review'},documents:[{id:uid(),title:'Supplier agreement — sample document',body:'SAMPLE — FOR LOCAL TESTING ONLY\n\nSupplier: {{supplier}}\nContract amount: {{amount}}\nContact: {{contact}}\nStatus: {{status}}\n\nScope: Design and deliver a sample website.\nTerms: Review the scope, budget, and final document before completing this local process.\n\nThis text is generated locally. No message is sent and no legally verified signature is collected.'}],fields:[{id:uid(),key:'supplier',label:'Supplier name',type:'text',required:true},{id:uid(),key:'amount',label:'Contract amount (finance review above 10000)',type:'number',required:true},{id:uid(),key:'contact',label:'Contact email — stored locally only',type:'email',required:true},{id:uid(),key:'status',label:'Agreement status',type:'text',required:false}],steps:[step(0,'Collect agreement details','form',[],50,180),step(1,'Legal review','approval',[0],360,50,{recipient:'Legal reviewer (local)'}),step(2,'Finance review · above 10,000','approval',[0],360,320,{recipient:'Finance reviewer (local)',condition:{field:'amount',op:'gt',value:'10000'}}),step(3,'Final acknowledgement','acknowledgement',[1,2],670,180,{recipient:'Document owner (local)'}),step(4,'Update document status','bot',[3],980,180,{bot:'prefill',field:'status',value:'Approved locally'}),step(5,'Tag completed package','bot',[4],1290,180,{bot:'tag',value:'sample-review-complete'})]};
 validate(w);db.workflows.push(w);persist('sample.workflow_loaded',w.name);
 }
 selected=w.steps[0]?.id;tab='diagram';location.hash='/editor/'+w.id;render();toast('Sample loaded. Start a local run to test the route; existing workflows are preserved.');
}
